//! Commands anchored at a pointer or beside a keyboard-focused target.
use crate::{
    foundation::Theme,
    primitives::{
        family::{Tone, face},
        menu::{MenuControl, MenuCore, MenuItem, MenuSelection, render_menu},
    },
};
use gpui::{prelude::*, *};
type Target = Box<dyn Fn(&mut Window, &mut App) -> AnyElement>;
pub struct ContextMenu {
    core: MenuCore,
    target: Target,
}
impl ContextMenu {
    pub fn new(
        id: impl Into<ElementId>,
        label: impl Into<SharedString>,
        items: Vec<MenuItem>,
        target: impl Fn(&mut Window, &mut App) -> AnyElement + 'static,
        cx: &App,
    ) -> Self {
        Self {
            core: MenuCore::new(id.into(), label.into(), items, cx),
            target: Box::new(target),
        }
    }
    pub fn is_open(&self) -> bool {
        self.core.open
    }
}
impl EventEmitter<MenuSelection> for ContextMenu {}
impl MenuControl for ContextMenu {
    fn core(&mut self) -> &mut MenuCore {
        &mut self.core
    }
    fn selected(&mut self, i: usize, w: &mut Window, cx: &mut Context<Self>) {
        let id = self.core.items[i].id.clone();
        self.core.close(w, cx);
        cx.emit(MenuSelection(id));
        cx.notify()
    }
}
impl Render for ContextMenu {
    fn render(&mut self, w: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        let target = (self.target)(w, cx);
        let btn = face(
            "target",
            self.core.name.clone(),
            44.,
            Theme::global(cx).tokens.radius.md.into(),
            Tone::Clear,
            cx,
        )
        .h_auto()
        .child(target);
        render_menu(self, btn, true, 208., w, cx)
    }
}

//! Focus and activation shared by installed action controls.
use crate::foundation::Theme;
use gpui::{
    App, Context, Div, ElementId, Role, SharedString, Stateful, Window, div, prelude::*, px,
};

pub fn surface(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &App,
) -> Stateful<Div> {
    let label = label.into();
    let c = &Theme::global(cx).tokens.colors;
    let outline = c.focus_outline;
    div()
        .id(id)
        .role(Role::Button)
        .debug_selector(|| label.to_string())
        .aria_label(label)
        .tab_index(0)
        .min_h(px(44.))
        .px_3()
        .flex()
        .items_center()
        .justify_center()
        .rounded(Theme::global(cx).tokens.radius.md)
        .border_1()
        .border_color(c.border)
        .bg(c.surface)
        .text_color(c.foreground)
        .cursor_pointer()
        .hover(|s| s.opacity(0.8))
        .focus_visible(move |s| {
            s.shadow(vec![gpui::BoxShadow {
                color: outline,
                offset: gpui::point(px(0.), px(0.)),
                blur_radius: px(0.),
                spread_radius: px(2.),
                inset: false,
            }])
        })
}

pub fn activate<T: 'static>(
    el: Stateful<Div>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    // GPUI turns a completed Enter/Space press into one keyboard ClickEvent.
    // Registering a second key-down action also toggles on key-up in Web hosts.
    el.on_click(cx.listener(move |v, _, w, cx| f(v, w, cx)))
}

pub fn action<T: 'static>(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    let label = label.into();
    activate(surface(id, label.clone(), cx).child(label), cx, f)
}

/// Secondary action with a text label and a full keyboard/touch target.
pub fn quiet<T: 'static>(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    let c = Theme::global(cx).tokens.colors.clone();
    action(id, label, cx, f)
        .border_0()
        .bg(gpui::transparent_black())
        .text_size(px(12.))
        .text_color(c.text_secondary)
}

/// Monochrome control marks drawn with the same paths on both renderers.
#[derive(Clone, Copy)]
pub enum Mark {
    Hold,
    Check,
    Mic,
    Stop,
    Chevron,
    Up,
    Spark,
    Heart,
}
pub fn mark(kind: Mark, ink: gpui::Hsla) -> impl IntoElement {
    use gpui::{PathBuilder, canvas, point};
    canvas(
        |_, _, _| (),
        move |b, _, w, _| {
            let at = |x: f32, y: f32| point(b.origin.x + px(x), b.origin.y + px(y));
            let mut p = PathBuilder::stroke(px(1.55));
            match kind {
                Mark::Hold => {
                    p.move_to(at(3., 10.));
                    p.curve_to(at(8., 2.5), at(2.4, 2.7));
                    p.curve_to(at(13.3, 8.), at(13.2, 2.5));
                    p.move_to(at(4.6, 13.));
                    p.curve_to(at(5.5, 7.5), at(6., 10.5));
                    p.curve_to(at(10.5, 7.5), at(8., 3.5));
                    p.curve_to(at(9.4, 14.), at(11.1, 10.5));
                    p.move_to(at(8., 7.5));
                    p.curve_to(at(7.2, 12.1), at(8.6, 9.2));
                }
                Mark::Check => {
                    p.move_to(at(2.3, 8.1));
                    p.line_to(at(6.5, 12.));
                    p.line_to(at(13.8, 3.6));
                }
                Mark::Mic => {
                    p.move_to(at(5.4, 4.));
                    p.curve_to(at(10.6, 4.), at(8., -0.9));
                    p.line_to(at(10.6, 7.8));
                    p.curve_to(at(5.4, 7.8), at(8., 12.5));
                    p.line_to(at(5.4, 4.));
                    p.move_to(at(2.5, 7.5));
                    p.curve_to(at(13.5, 7.5), at(8., 16.5));
                    p.move_to(at(8., 12.));
                    p.line_to(at(8., 15.));
                    p.move_to(at(5.5, 15.));
                    p.line_to(at(10.5, 15.));
                }
                Mark::Stop => {
                    p = PathBuilder::fill();
                    p.move_to(at(3.5, 3.5));
                    p.line_to(at(12.5, 3.5));
                    p.line_to(at(12.5, 12.5));
                    p.line_to(at(3.5, 12.5));
                    p.close();
                }
                Mark::Up => {
                    p.move_to(at(8., 13.5));
                    p.line_to(at(8., 2.5));
                    p.move_to(at(3.2, 7.5));
                    p.line_to(at(8., 2.5));
                    p.line_to(at(12.8, 7.5));
                }
                Mark::Spark => {
                    p.move_to(at(8., 1.5));
                    p.curve_to(at(14.5, 8.), at(9.2, 6.7));
                    p.curve_to(at(8., 14.5), at(9.2, 9.3));
                    p.curve_to(at(1.5, 8.), at(6.8, 9.3));
                    p.curve_to(at(8., 1.5), at(6.8, 6.7));
                    p.close();
                }
                Mark::Heart => {
                    p.move_to(at(8., 13.8));
                    p.cubic_bezier_to(at(1.8, 5.6), at(5., 11.5), at(1.8, 8.6));
                    p.cubic_bezier_to(at(8., 4.4), at(1.8, 2.), at(5.8, 1.6));
                    p.cubic_bezier_to(at(14.2, 5.6), at(10.2, 1.6), at(14.2, 2.));
                    p.cubic_bezier_to(at(8., 13.8), at(14.2, 8.6), at(11., 11.5));
                    p.close();
                }
                Mark::Chevron => {
                    p.move_to(at(5., 6.5));
                    p.line_to(at(8., 9.5));
                    p.line_to(at(11., 6.5));
                }
            }
            if let Ok(path) = p.build() {
                w.paint_path(path, ink);
            }
        },
    )
    .size(px(16.))
    .flex_none()
}

/// Optional host language for labels owned by action controls; English is the default.
#[derive(Clone, Copy, Default, PartialEq, Eq)]
pub enum UiLanguage {
    #[default]
    English,
    Chinese,
}
impl gpui::Global for UiLanguage {}
impl UiLanguage {
    pub fn current(cx: &App) -> Self {
        cx.try_global::<Self>().copied().unwrap_or_default()
    }
    pub fn text<'a>(self, english: &'a str, chinese: &'a str) -> &'a str {
        match self {
            Self::English => english,
            Self::Chinese => chinese,
        }
    }
}

//! Compact action surfaces scoped to the button family.
use crate::foundation::{AccentPalette, Theme, ThemeMode};
use gpui::{prelude::*, *};
use web_time::Instant;
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub enum Tone {
    #[default]
    Surface,
    Primary,
    Muted,
    Danger,
    Success,
    Clear,
}
#[derive(Clone, Copy)]
pub struct Paint {
    pub stage: Hsla,
    pub panel: Hsla,
    pub tray: Hsla,
    pub hover: Hsla,
    pub ink: Hsla,
    pub secondary: Hsla,
    pub faint: Hsla,
    pub line: Hsla,
    pub bright: Hsla,
    pub(crate) focus: Hsla,
    pub inverse: Hsla,
    pub(crate) neutral_inverse: Hsla,
    accent: AccentPalette,
    pub danger: Hsla,
    pub success: Hsla,
}
impl Paint {
    pub fn get(cx: &App) -> Self {
        Self::for_theme(Theme::global(cx))
    }
    pub(crate) fn for_theme(theme: &Theme) -> Self {
        let mut paint = Self::for_mode(theme.mode);
        let tint = theme.accent.for_mode(theme.mode);
        if tint.is_transparent() {
            return paint;
        }
        paint.accent = theme.accent;
        paint.bright = paint.bright.blend(tint);
        paint.focus = theme.tokens.colors.focus_outline;
        paint.inverse = paint.accent.on_fill(paint.bright, paint.neutral_inverse);
        paint.hover = paint.hover.blend(tint.opacity(0.12));
        paint
    }
    pub(crate) fn primary_hover(self, strength: f32) -> Hsla {
        self.bright.blend(
            self.accent
                .hover_tint(self.bright, self.inverse, strength)
                .opacity(strength),
        )
    }
    pub fn for_mode(mode: ThemeMode) -> Self {
        let dark = mode == ThemeMode::Dark;
        let [
            stage,
            panel,
            tray,
            hover,
            ink,
            secondary,
            faint,
            line,
            bright,
            inverse,
            danger,
        ] = if dark {
            [
                0x242424, 0x191919, 0x303030, 0x353535, 0xf2f2f2, 0xb5b5b5, 0x898989, 0x2b2b2b,
                0xf2f2f2, 0x141414, 0xff746f,
            ]
        } else {
            [
                0xf5f5f5, 0xffffff, 0xffffff, 0xe9e9e9, 0x1a1a1a, 0x575757, 0x747474, 0xe2e2e2,
                0x181818, 0xfafafa, 0xbd302c,
            ]
        };
        Self {
            stage: rgb(stage).into(),
            panel: rgb(panel).into(),
            tray: rgb(tray).into(),
            hover: rgb(hover).into(),
            ink: rgb(ink).into(),
            secondary: rgb(secondary).into(),
            faint: rgb(faint).into(),
            line: rgb(line).into(),
            bright: rgb(bright).into(),
            focus: rgb(bright).into(),
            inverse: rgb(inverse).into(),
            neutral_inverse: rgb(inverse).into(),
            accent: AccentPalette::default(),
            danger: rgb(danger).into(),
            success: rgb(if dark { 0x53d986 } else { 0x008039 }).into(),
        }
    }
    pub fn colors(self, t: Tone) -> (Hsla, Hsla) {
        match t {
            Tone::Primary => (self.bright, self.inverse),
            Tone::Success => (self.panel.blend(self.success.opacity(0.10)), self.ink),
            Tone::Muted => (self.secondary, self.neutral_inverse),
            Tone::Clear => (transparent_black(), self.ink),
            _ => (self.panel, self.ink),
        }
    }
}
pub fn face(
    id: impl Into<ElementId>,
    name: impl Into<SharedString>,
    height: f32,
    r: f32,
    t: Tone,
    cx: &App,
) -> Stateful<Div> {
    let p = Paint::get(cx);
    let (bg, fg) = p.colors(t);
    let name = name.into();
    let ring = Theme::global(cx).tokens.colors.focus_outline;
    div()
        .id(id)
        .debug_selector({
            let name = name.clone();
            move || name.to_string()
        })
        .aria_label(name)
        .role(Role::Button)
        .tab_index(0)
        .h(px(height))
        .flex_none()
        .flex()
        .items_center()
        .justify_center()
        .gap(px(8.))
        .rounded(px(r))
        .bg(bg)
        .text_color(fg)
        .text_size(px(14.))
        .line_height(px(19.6))
        .font_weight(FontWeight::MEDIUM)
        .whitespace_nowrap()
        .cursor_pointer()
        .when(t == Tone::Danger, |e| {
            e.border_1().border_color(p.danger.opacity(0.42))
        })
        .when(t == Tone::Success, |e| {
            e.border_1().border_color(p.success.opacity(0.40))
        })
        .focus_visible(move |s| s.border_1().border_color(ring))
}
/// Analytic critically damped spring. Retargeting preserves instantaneous velocity.
#[derive(Clone, Copy, Debug)]
pub struct Slide {
    from: f32,
    to: f32,
    velocity: f32,
    start: Option<Instant>,
    omega: f32,
}
impl Slide {
    pub fn new(v: f32) -> Self {
        Self {
            from: v,
            to: v,
            velocity: 0.,
            start: None,
            omega: 12.47,
        }
    }
    pub fn snappy(v: f32) -> Self {
        Self {
            omega: 20.14,
            ..Self::new(v)
        }
    }
    /// Re-express the same trajectory in a shifted coordinate system, preserving velocity.
    pub fn translate(&mut self, delta: f32) {
        self.from += delta;
        self.to += delta;
    }
    pub fn reset(&mut self, v: f32) {
        self.from = v;
        self.to = v;
        self.velocity = 0.;
        self.start = None;
    }
    pub fn set(&mut self, v: f32, cx: &App) {
        self.retarget(v, self.omega, cx);
    }
    pub fn duration(&mut self, v: f32, visual_seconds: f32, cx: &App) {
        self.retarget(v, 5.236 / visual_seconds, cx)
    }
    /// Settle a directly manipulated value with the measured release speed (units per second).
    pub(crate) fn release(&mut self, target: f32, velocity: f32, seconds: f32, cx: &App) {
        if disabled_motion(cx) {
            self.reset(target);
            return;
        }
        let now = cx.background_executor().now();
        self.from = self.sample(now).0;
        self.to = target;
        self.velocity = velocity;
        self.omega = 5.236 / seconds;
        self.start = Some(now);
    }
    /// Stagger a first reveal without advancing the value before its slot starts.
    pub(crate) fn delayed(&mut self, target: f32, seconds: f32, delay: f32, cx: &App) {
        if self.to == target {
            return;
        }
        self.duration(target, seconds, cx);
        if let Some(start) = self.start.as_mut() {
            *start += std::time::Duration::from_secs_f32(delay.max(0.));
        }
    }
    fn retarget(&mut self, v: f32, omega: f32, cx: &App) {
        if disabled_motion(cx) {
            self.reset(v);
            return;
        }
        if self.to == v {
            return;
        }
        let now = cx.background_executor().now();
        let (pos, vel, _) = self.sample(now);
        self.from = pos;
        self.velocity = vel;
        self.omega = omega;
        self.to = v;
        self.start = Some(now);
    }
    fn sample(&self, now: Instant) -> (f32, f32, bool) {
        let Some(start) = self.start else {
            return (self.to, 0., false);
        };
        let t = now.saturating_duration_since(start).as_secs_f32();
        let d = self.from - self.to;
        let k = self.velocity + self.omega * d;
        let e = (-self.omega * t).exp();
        let offset = (d + k * t) * e;
        let vel = (self.velocity - self.omega * k * t) * e;
        if offset.abs() < 0.0008 && vel.abs() < 0.012 || t > 1.6 {
            (self.to, 0., false)
        } else {
            (self.to + offset, vel, true)
        }
    }
    /// Sample from an input handler without scheduling a frame outside paint.
    pub fn value(&self, cx: &App) -> f32 {
        if disabled_motion(cx) {
            self.to
        } else {
            self.sample(cx.background_executor().now()).0
        }
    }
    pub fn get(&self, w: &Window, cx: &App) -> f32 {
        if disabled_motion(cx) {
            return self.to;
        }
        let (v, _, m) = self.sample(cx.background_executor().now());
        if m {
            w.request_animation_frame()
        }
        v
    }
}
pub fn disabled_motion(cx: &App) -> bool {
    cx.try_global::<Theme>().is_some_and(|t| t.reduced_motion)
}
/// A finite paint clock; never schedules frames once its last phase has finished.
#[derive(Clone, Copy, Default, Debug)]
pub struct PhaseClock(Option<Instant>);
impl PhaseClock {
    pub fn restart(&mut self, cx: &App) {
        self.0 = Some(cx.background_executor().now())
    }
    pub fn age(self, cx: &App) -> f32 {
        self.0.map_or(f32::INFINITY, |s| {
            cx.background_executor()
                .now()
                .saturating_duration_since(s)
                .as_secs_f32()
        })
    }
    pub fn time(self, end: f32, w: &Window, cx: &App) -> f32 {
        if disabled_motion(cx) {
            return end;
        }
        let t = self.age(cx);
        if t < end {
            w.request_animation_frame()
        }
        t.min(end)
    }
}
pub fn ease(t: f32) -> f32 {
    cubic_out(t, 0.16, 0.30)
}
/// Cubic-bezier(.22, 1, .36, 1) used by page-scale wipes.
pub fn standard_ease(x: f32) -> f32 {
    cubic_out(x, 0.22, 0.36)
}
fn cubic_out(x: f32, x1: f32, x2: f32) -> f32 {
    if x <= 0. || x >= 1. {
        return x.clamp(0., 1.);
    }
    let (mut lo, mut hi) = (0., 1.);
    for _ in 0..14 {
        let t = (lo + hi) * 0.5;
        let v = 1. - t;
        let at = 3. * x1 * v * v * t + 3. * x2 * v * t * t + t * t * t;
        if at < x { lo = t } else { hi = t }
    }
    1. - (1. - (lo + hi) * 0.5_f32).powi(3)
}
pub fn measure(text: &SharedString, size: f32, w: &Window) -> f32 {
    let mut style = w.text_style();
    style.font_weight = FontWeight::MEDIUM;
    let advance: f32 = w
        .text_system()
        .shape_line(text.clone(), px(size), &[style.to_run(text.len())], None)
        .width
        .into();
    (advance - 0.01 * size * text.chars().count() as f32).max(0.)
}
/// Pointer feedback lives in the element's stable hit box, independent of its paint.
pub fn press<T: 'static>(
    el: Stateful<Div>,
    cx: &Context<T>,
    field: fn(&mut T) -> &mut Slide,
) -> Stateful<Div> {
    el.on_mouse_down(
        MouseButton::Left,
        cx.listener(move |v, _, _, cx| {
            field(v).set(1., cx);
            cx.notify()
        }),
    )
    .on_mouse_up(
        MouseButton::Left,
        cx.listener(move |v, _, _, cx| {
            field(v).set(0., cx);
            cx.notify()
        }),
    )
    .on_mouse_up_out(
        MouseButton::Left,
        cx.listener(move |v, _, _, cx| {
            field(v).set(0., cx);
            cx.notify()
        }),
    )
    .on_key_down(cx.listener(move |v, e: &KeyDownEvent, _, cx| {
        if matches!(e.keystroke.key.as_str(), "enter" | "space") {
            field(v).set(1., cx);
            cx.notify()
        }
    }))
    .on_key_up(cx.listener(move |v, e: &KeyUpEvent, _, cx| {
        if matches!(e.keystroke.key.as_str(), "enter" | "space") {
            field(v).set(0., cx);
            cx.notify()
        }
    }))
}

/// Stable glyph identities are matched in reading order, including common suffixes.
fn shared_glyphs(
    left: &[(SharedString, f32)],
    right: &[(SharedString, f32)],
) -> Vec<Option<usize>> {
    let stride = right.len() + 1;
    let mut lcs = vec![0u16; (left.len() + 1) * stride];
    for i in (0..left.len()).rev() {
        for j in (0..right.len()).rev() {
            lcs[i * stride + j] = if left[i].0 == right[j].0 {
                1 + lcs[(i + 1) * stride + j + 1]
            } else {
                lcs[(i + 1) * stride + j].max(lcs[i * stride + j + 1])
            };
        }
    }
    let mut out = vec![None; left.len()];
    let (mut i, mut j) = (0, 0);
    while i < left.len() && j < right.len() {
        if left[i].0 == right[j].0 {
            out[i] = Some(j);
            i += 1;
            j += 1
        } else if lcs[(i + 1) * stride + j] >= lcs[i * stride + j + 1] {
            i += 1
        } else {
            j += 1
        }
    }
    out
}
/// Paint two label phases in one measured slot; the outgoing face never affects layout.
pub fn lettering(
    old: SharedString,
    new: SharedString,
    time: f32,
    letters: bool,
    size: f32,
    ink: Hsla,
    width: f32,
) -> impl IntoElement {
    canvas(
        |_, _, _| (),
        move |b, _, w, cx| {
            let plain = old == new || time >= 0.48;
            let mut style = w.text_style();
            style.font_weight = FontWeight::MEDIUM;
            let width_of = |s: &SharedString| {
                f32::from(
                    w.text_system()
                        .shape_line(s.clone(), px(size), &[style.to_run(s.len())], None)
                        .width,
                )
            };
            let old_x = (width - width_of(&old)) * 0.5;
            let new_x = (width - width_of(&new)) * 0.5;
            if plain {
                let mut run = style.to_run(new.len());
                run.color = ink;
                let line = w
                    .text_system()
                    .shape_line(new.clone(), px(size), &[run], None);
                let _ = line.paint(
                    b.origin + point(px(new_x), px(0.)),
                    b.size.height,
                    TextAlign::Left,
                    None,
                    w,
                    cx,
                );
                return;
            }
            let pieces = |s: &SharedString| -> Vec<(SharedString, f32)> {
                let line =
                    w.text_system()
                        .shape_line(s.clone(), px(size), &[style.to_run(s.len())], None);
                s.char_indices()
                    .map(|(i, c)| (c.to_string().into(), line.x_for_index(i).into()))
                    .collect()
            };
            let mut runs = Vec::new();
            if letters && old.len() < 256 && new.len() < 256 {
                let left = pieces(&old);
                let right = pieces(&new);
                let pairs = shared_glyphs(&left, &right);
                let mut stable = vec![false; right.len()];
                let out = 1. - standard_ease(time / 0.16);
                let layout = 1. - (1. + 12.47 * time) * (-12.47 * time).exp();
                for ((glyph, dx), matched) in left.into_iter().zip(pairs) {
                    if let Some(j) = matched {
                        let x = old_x + dx;
                        stable[j] = true;
                        runs.push((glyph, x + (new_x + right[j].1 - x) * layout, 0., 1., 0.));
                    } else {
                        runs.push((glyph, old_x + dx, -3. * (1. - out), out, 2. * (1. - out)));
                    }
                }
                let mut order = 0;
                for ((glyph, dx), matched) in right.into_iter().zip(stable) {
                    if !matched {
                        let k = ease((time - (order as f32 * 0.016).min(0.1)) / 0.24);
                        runs.push((glyph, new_x + dx, 4. * (1. - k), k, 2. * (1. - k)));
                        order += 1;
                    }
                }
            } else {
                let incoming = ease(time / 0.16);
                runs.push((old.clone(), old_x, 0., 1. - standard_ease(time / 0.10), 0.));
                runs.push((new.clone(), new_x, 2. * (1. - incoming), incoming, 0.));
            }
            for (s, x, y, alpha, blur) in runs {
                if alpha < 0.001 || s.is_empty() {
                    continue;
                }
                let taps = if blur > 0.22 { 5 } else { 1 };
                let mut run = style.to_run(s.len());
                run.color = ink.opacity(alpha / if taps == 5 { 4.3 } else { 1. });
                let line = w.text_system().shape_line(s, px(size), &[run], None);
                for (dx, dy) in [(0., 0.), (-0.7, 0.), (0.7, 0.), (0., -0.7), (0., 0.7)]
                    .into_iter()
                    .take(taps)
                {
                    let _ = line.paint(
                        b.origin + point(px(x + dx * blur), px(y + dy * blur)),
                        b.size.height,
                        TextAlign::Left,
                        None,
                        w,
                        cx,
                    );
                }
            }
        },
    )
    .w(px(width.max(0.)))
    .h(px(size * 1.4))
    .flex_none()
}

#[cfg(test)]
mod spring_tests {
    use super::{Instant, Slide};
    use std::time::Duration;
    #[test]
    fn reversing_keeps_position_and_velocity() {
        let s = Instant::now();
        let mid = s + Duration::from_millis(75);
        let a = Slide {
            start: Some(s),
            to: 1.,
            ..Slide::new(0.)
        };
        let (x, v, _) = a.sample(mid);
        let reversed = Slide {
            start: Some(mid),
            from: x,
            velocity: v,
            to: 0.,
            ..a
        };
        assert_eq!(reversed.sample(mid), (x, v, true));
        assert!(reversed.sample(mid + Duration::from_millis(240)).0 < x);
        assert_eq!(
            reversed.sample(mid + Duration::from_secs(2)),
            (0., 0., false)
        );
    }
    #[test]
    fn unchanged_suffix_keeps_its_identity_across_label_swaps() {
        let glyphs = |s: &str| {
            s.chars()
                .map(|g| (gpui::SharedString::from(g.to_string()), 0.))
                .collect::<Vec<_>>()
        };
        let old = glyphs("Add to library");
        let new = glyphs("In library");
        let pairs = super::shared_glyphs(&old, &new);
        assert_eq!(
            &pairs[old.len() - 7..],
            &[
                Some(3),
                Some(4),
                Some(5),
                Some(6),
                Some(7),
                Some(8),
                Some(9)
            ]
        );
        assert_eq!(
            super::shared_glyphs(&glyphs("添加成员"), &glyphs("移除成员")),
            vec![None, None, Some(2), Some(3)]
        );
    }
}

#[cfg(test)]
mod accent_tests {
    use super::{AccentPalette, Paint, Theme, ThemeMode};
    use gpui::{Hsla, rgb};
    #[test]
    fn custom_accent_preserves_fill_and_picks_readable_ink_in_both_modes() {
        // Color pairs include near-threshold grays and hues with high/low relative
        // luminance despite identical HSL lightness (yellow and blue).
        for (hex, expected) in [
            (0xffffff, Hsla::black()),
            (0x000000, Hsla::white()),
            (0xffff00, Hsla::black()),
            (0x0000ff, Hsla::white()),
            (0x757575, Hsla::white()),
            (0x767676, Hsla::black()),
            (0xdfa4ef, Hsla::black()),
            (0x221144, Hsla::white()),
        ] {
            let fill: Hsla = rgb(hex).into();
            let accent = AccentPalette {
                light: fill,
                dark: fill,
            };
            let mut theme = Theme::default();
            theme.set_accent(accent);
            for mode in [ThemeMode::Light, ThemeMode::Dark] {
                theme.set_mode(mode);
                let colors = &theme.tokens.colors;
                let p = Paint::for_theme(&theme);
                assert_eq!(colors.accent, fill);
                assert_eq!(p.bright, fill);
                assert_eq!(colors.accent_foreground, expected, "#{hex:06x}");
                assert_eq!(p.inverse, expected);
                assert!(AccentPalette::contrast(p.inverse, p.bright) >= 4.5);
                assert!(AccentPalette::contrast(p.inverse, p.primary_hover(0.12)) >= 4.5);
                assert!(AccentPalette::contrast(colors.focus_outline, colors.surface_muted) >= 3.5);
                assert!(AccentPalette::contrast(colors.focus_outline, p.stage) >= 3.);
                // A tint applies to the primary fill, never to text on neutral/status surfaces.
                assert_eq!(p.neutral_inverse, Paint::for_mode(mode).inverse);
            }
        }
    }

    #[test]
    fn theme_presets_keep_their_authored_inks_and_focus_colors() {
        for (light, dark) in [
            (0x245bc4, 0x8bb4ff),
            (0x7142b6, 0xbc9cff),
            (0x08776d, 0x68d4c4),
            (0xb93c67, 0xff94b3),
            (0x955a08, 0xf4be69),
        ] {
            let mut theme = Theme::default();
            let pair = AccentPalette {
                light: rgb(light).into(),
                dark: rgb(dark).into(),
            };
            theme.set_accent(pair);
            for mode in [ThemeMode::Light, ThemeMode::Dark] {
                theme.set_mode(mode);
                let p = Paint::for_theme(&theme);
                let neutral = Paint::for_mode(mode);
                assert_eq!(p.bright, pair.for_mode(mode));
                assert_eq!(p.inverse, neutral.inverse);
                assert_eq!(theme.tokens.colors.focus_outline, pair.for_mode(mode));
            }
            theme.set_accent(AccentPalette::default());
            let p = Paint::for_theme(&theme);
            let neutral = Paint::for_mode(theme.mode);
            assert_eq!(p.bright, neutral.bright);
            assert_eq!(p.inverse, neutral.inverse);
        }
    }
}

//! Direct contact input for controls that cannot wait for a synthesized tap.
use gpui::{prelude::*, *};
use std::{cell::Cell, rc::Rc};
#[derive(Default, Clone)]
pub(crate) struct Contact(Rc<Cell<bool>>);
impl Contact {
    /// Mount over the gesture target. Only the topmost, hovered hitbox may claim a new contact.
    pub(crate) fn listen<T: 'static>(
        &self,
        cx: &Context<T>,
        handle: impl Fn(&mut T, &TouchDragEvent, &mut Window, &mut Context<T>) + 'static,
    ) -> impl IntoElement {
        let listener = cx.listener(handle);
        let active = self.0.clone();
        canvas(
            |bounds, w, _| w.insert_hitbox(bounds, HitboxBehavior::Normal),
            move |_, hit, w, _| {
                w.on_mouse_event(move |e: &TouchDragEvent, phase, w, cx| {
                    if phase.bubble() {
                        if e.phase == TouchPhase::Started {
                            active.set(hit.is_hovered(w));
                        }
                        if !active.get() {
                            return;
                        }
                        if matches!(e.phase, TouchPhase::Ended | TouchPhase::Cancelled) {
                            active.set(false)
                        }
                        if e.phase == TouchPhase::Started {
                            w.prevent_default();
                        }
                        listener(e, w, cx);
                        cx.stop_propagation();
                    }
                })
            },
        )
        .absolute()
        .inset_0()
    }
}

//! Anchoring, dismissal and roving selection shared by command menus.
use crate::{
    foundation::Theme,
    primitives::{
        direct_touch::Contact,
        family::{Paint, PhaseClock, Slide, ease},
        glyph::{Glyph, icon},
    },
};
use gpui::{prelude::*, *};
use std::{cell::Cell, rc::Rc};

#[derive(Clone, Debug, PartialEq, Eq)]
pub struct MenuItem {
    pub id: SharedString,
    pub label: SharedString,
    pub glyph: Option<Glyph>,
    pub disabled: bool,
    pub destructive: bool,
    pub separator_before: bool,
    pub shortcut: SharedString,
    pub checked: Option<bool>,
}
impl MenuItem {
    pub fn new(id: impl Into<SharedString>, label: impl Into<SharedString>) -> Self {
        Self {
            id: id.into(),
            label: label.into(),
            glyph: None,
            disabled: false,
            destructive: false,
            separator_before: false,
            shortcut: "".into(),
            checked: None,
        }
    }
    pub fn with_icon(mut self, g: Glyph) -> Self {
        self.glyph = Some(g);
        self
    }
    pub fn with_separator(mut self) -> Self {
        self.separator_before = true;
        self
    }
    pub fn destructive(mut self) -> Self {
        self.destructive = true;
        self
    }
    pub fn disabled(mut self) -> Self {
        self.disabled = true;
        self
    }
    pub fn checked(mut self, checked: bool) -> Self {
        self.checked = Some(checked);
        self
    }
    pub fn with_shortcut(mut self, s: impl Into<SharedString>) -> Self {
        self.shortcut = s.into();
        self
    }
}
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct MenuSelection(pub SharedString);

/// Horizontal placement relative to an anchored trigger.
#[derive(Default, Debug, Clone, Copy, PartialEq, Eq)]
pub enum MenuAlign {
    Start,
    Center,
    #[default]
    End,
}
pub(crate) struct MenuCore {
    pub align: MenuAlign,
    pub id: ElementId,
    pub items: Vec<MenuItem>,
    pub name: SharedString,
    pub trigger: FocusHandle,
    focus: FocusHandle,
    pub open: bool,
    pub anchor: Rc<Cell<Bounds<Pixels>>>,
    point: Option<Point<Pixels>>,
    active: Option<usize>,
    highlight: Slide,
    pub(crate) appear: Slide,
    clock: PhaseClock,
    viewport: Size<Pixels>,
    row_height: f32,
    sheet_drag: Slide,
    sheet_touch: Contact,
}
impl MenuCore {
    pub fn new(id: ElementId, name: SharedString, items: Vec<MenuItem>, cx: &App) -> Self {
        Self {
            id,
            align: MenuAlign::End,
            name,
            items,
            trigger: cx.focus_handle().tab_stop(true),
            focus: cx.focus_handle(),
            open: false,
            anchor: Default::default(),
            point: None,
            active: None,
            highlight: Slide::snappy(0.),
            appear: Slide::snappy(0.),
            clock: Default::default(),
            viewport: Default::default(),
            row_height: 36.,
            sheet_drag: Slide::snappy(0.),
            sheet_touch: Default::default(),
        }
    }
    fn top(&self, i: usize) -> f32 {
        self.items
            .iter()
            .take(i + 1)
            .filter(|r| r.separator_before)
            .count() as f32
            * 9.
            + i as f32 * self.row_height
    }
    pub fn show(
        &mut self,
        point: Option<Point<Pixels>>,
        keyboard: bool,
        last: bool,
        w: &mut Window,
        cx: &mut App,
    ) {
        self.sheet_drag.reset(0.);
        self.point = point;
        self.open = true;
        self.appear.set(1., cx);
        self.clock.restart(cx);
        self.viewport = w.viewport_size();
        self.active = if last {
            self.items.iter().rposition(|r| !r.disabled)
        } else {
            self.items.iter().position(|r| !r.disabled)
        };
        self.visible_highlight(keyboard);
        self.focus.focus(w, cx)
    }
    fn visible_highlight(&mut self, show: bool) {
        if !show {
            self.active = None
        }
        if let Some(i) = self.active {
            self.highlight.reset(self.top(i))
        }
    }
    pub fn close(&mut self, w: &mut Window, cx: &mut App) {
        if self.open {
            self.open = false;
            self.appear.duration(0., 0.13, cx);
            self.trigger.focus(w, cx)
        }
    }
}
pub(crate) trait MenuControl: Sized + 'static {
    fn core(&mut self) -> &mut MenuCore;
    fn selected(&mut self, i: usize, w: &mut Window, cx: &mut Context<Self>);
    fn header(&self, _: &App) -> Option<AnyElement> {
        None
    }
    fn accessory(&self, _: usize, _: &Context<Self>, _: &Window) -> Option<AnyElement> {
        None
    }
    fn horizontal(&mut self, _: usize, _: bool, _: &mut Context<Self>) {}
    fn compact(&self, _: &Window) -> bool {
        false
    }
}
fn key<T: MenuControl>(v: &mut T, e: &KeyDownEvent, w: &mut Window, cx: &mut Context<T>) {
    let m = v.core();
    let k = e.keystroke.key.as_str();
    if !m.open {
        return;
    }
    let enabled: Vec<_> = m
        .items
        .iter()
        .enumerate()
        .filter(|(_, r)| !r.disabled)
        .map(|(i, _)| i)
        .collect();
    let curr = m.active.and_then(|i| enabled.iter().position(|j| *j == i));
    let n = enabled.len();
    match k {
        "escape" | "tab" => {
            m.close(w, cx);
            if k == "tab" {
                if e.keystroke.modifiers.shift {
                    w.focus_prev(cx)
                } else {
                    w.focus_next(cx)
                }
            }
        }
        "enter" | "space" => {
            if let Some(i) = m.active.or_else(|| enabled.first().copied()) {
                v.selected(i, w, cx)
            }
        }
        "left" | "right" => {
            if let Some(i) = m.active {
                v.horizontal(i, k == "right", cx)
            }
        }
        _ if n > 0 => {
            let i = match k {
                "down" => enabled[curr.map_or(0, |j| (j + 1) % n)],
                "up" => enabled[curr.map_or(n - 1, |j| (j + n - 1) % n)],
                "home" => enabled[0],
                "end" => enabled[n - 1],
                s if s.chars().count() == 1 => {
                    let search = s.to_lowercase();
                    let Some(id) = (1..=n)
                        .map(|j| enabled[(curr.unwrap_or(n - 1) + j) % n])
                        .find(|i| m.items[*i].label.to_lowercase().starts_with(&search))
                    else {
                        return;
                    };
                    id
                }
                _ => return,
            };
            m.active = Some(i);
            m.highlight.reset(m.top(i));
        }
        _ => return,
    }
    w.prevent_default();
    cx.stop_propagation();
    cx.notify();
}
/// Add the trigger and an out-of-flow panel to the same stable element.
pub(crate) fn render_menu<T: MenuControl>(
    v: &mut T,
    button: Stateful<Div>,
    context: bool,
    width: f32,
    w: &mut Window,
    cx: &mut Context<T>,
) -> AnyElement {
    let p = Paint::get(cx);
    let rad = Theme::global(cx).tokens.radius.clone();
    let sheet = v.compact(w);
    let header = v.header(cx);
    let header_h = if header.is_some() { 62. } else { 0. };
    let m = v.core();
    let name = m.name.clone();
    let anchor = m.anchor.clone();
    let bounds = anchor.get();
    if context && m.open && m.viewport != w.viewport_size() {
        m.close(w, cx)
    }
    let row_height = if sheet {
        46.
    } else if header.is_some() {
        32.
    } else {
        36.
    };
    m.row_height = row_height;
    let grip_h = if sheet { 22. } else { 0. };
    let is_open = m.open;
    let mut btn = button
        .track_focus(&m.trigger)
        .aria_expanded(is_open)
        .on_click(cx.listener(|v, _, w, cx| {
            let m = v.core();
            if m.open {
                m.close(w, cx)
            } else {
                m.show(None, false, false, w, cx)
            }
            cx.notify()
        }))
        .on_key_down(cx.listener(move |v, e: &KeyDownEvent, w, cx| {
            let k = e.keystroke.key.as_str();
            if matches!(k, "down" | "up" | "enter" | "space")
                || context && (k == "contextmenu" || k == "f10" && e.keystroke.modifiers.shift)
            {
                if !e.is_held {
                    v.core().show(None, true, k == "up", w, cx);
                    cx.notify()
                }
                w.prevent_default();
                cx.stop_propagation()
            }
        }));
    if context {
        btn = btn.on_mouse_down(
            MouseButton::Right,
            cx.listener(|v, e: &MouseDownEvent, w, cx| {
                v.core().show(Some(e.position), false, false, w, cx);
                cx.notify();
                cx.stop_propagation()
            }),
        );
    }
    let mut root = div()
        .relative()
        .child(btn)
        .on_children_prepainted(move |b, _, _| {
            if let Some(b) = b.first() {
                anchor.set(*b)
            }
        })
        .id(m.id.clone());
    let anim = m.appear.get(w, cx).clamp(0., 1.);
    if (!is_open && anim < 0.015) || bounds.size.width <= px(0.) {
        if is_open && bounds.size.width <= px(0.) {
            w.request_animation_frame()
        }
        return root.into_any_element();
    }
    let size = w.viewport_size();
    let height = (12.
        + m.items.len() as f32 * row_height
        + grip_h
        + m.items.iter().filter(|r| r.separator_before).count() as f32 * 9.
        + header_h)
        .min(f32::from(size.height) - 16.);
    let width = if sheet {
        f32::from(size.width)
    } else {
        width.min(f32::from(size.width) - 16.)
    }
    .max(1.);
    let origin = m.point.unwrap_or_else(|| {
        point(
            if context {
                bounds.left() + px(12.)
            } else {
                match m.align {
                    MenuAlign::Start => bounds.left(),
                    MenuAlign::Center => bounds.center().x - px(width * 0.5),
                    MenuAlign::End => bounds.right() - px(width),
                }
            },
            bounds.bottom() + px(8.),
        )
    });
    let y = if sheet {
        f32::from(size.height) - height + (1. - anim) * height + m.sheet_drag.get(w, cx)
    } else if m.point.is_none()
        && origin.y + px(height) > size.height - px(8.)
        && bounds.top() > px(height)
    {
        f32::from(bounds.top()) - height - 8.
    } else {
        f32::from(origin.y)
    };
    let x = if sheet {
        (f32::from(size.width) - width) / 2.
    } else {
        f32::from(origin.x).clamp(8., (f32::from(size.width) - width - 8.).max(8.))
    };
    let y = if sheet {
        y
    } else {
        y.clamp(8., (f32::from(size.height) - height - 8.).max(8.)) - (1. - anim) * 5.
    };
    let trigger = m.anchor.clone();
    let active = m.active;
    let high = m.highlight.get(w, cx);
    let age = m.clock.time(0.35, w, cx);
    let rows = m.items.clone();
    let sheet_touch = m.sheet_touch.clone();
    let focus = m.focus.clone();
    let mut panel = div()
        .id("menu-panel")
        .role(Role::Menu)
        .aria_label(name)
        .track_focus(&focus)
        .tab_stop(false)
        .occlude()
        .relative()
        .w(px(width))
        .max_h(size.height - px(16.))
        .p(px(5.))
        .rounded(rad.md)
        .when(sheet, |e| e.rounded_b(px(0.)))
        .border_1()
        .border_color(p.line)
        .bg(p.panel)
        .shadow_lg()
        .opacity(anim)
        .flex()
        .flex_col()
        .overflow_y_scroll()
        .on_key_down(cx.listener(key::<T>))
        .on_mouse_down_out(cx.listener(move |v, e: &MouseDownEvent, w, cx| {
            if v.core().open && !trigger.get().contains(&e.position) {
                v.core().close(w, cx);
                cx.notify()
            }
        }));
    if sheet {
        let handle = div()
            .relative()
            .h(px(grip_h))
            .flex_none()
            .flex()
            .justify_center()
            .items_center()
            .child(div().w(px(34.)).h(px(4.)).rounded_full().bg(p.faint))
            .child(sheet_touch.listen(cx, |v, e, w, cx| {
                let m = v.core();
                let dy = f32::from(e.position.y - e.start_position.y).max(0.);
                match e.phase {
                    TouchPhase::Moved => m.sheet_drag.reset(dy),
                    TouchPhase::Ended if dy > 48. => m.close(w, cx),
                    TouchPhase::Ended | TouchPhase::Cancelled => m.sheet_drag.set(0., cx),
                    _ => {}
                }
                cx.notify()
            }));
        panel = panel.child(handle);
    }
    if let Some(header) = header {
        panel = panel.child(header)
    }
    if let Some(i) = active {
        panel = panel.child(
            div()
                .absolute()
                .top(px(5. + grip_h + header_h + high))
                .left(px(5.))
                .right(px(5.))
                .h(px(row_height))
                .rounded(rad.md)
                .bg(if rows[i].destructive {
                    p.danger.opacity(0.11)
                } else {
                    p.hover
                }),
        );
    }
    for (i, item) in rows.into_iter().enumerate() {
        if item.separator_before {
            panel = panel.child(div().my(px(4.)).h(px(1.)).bg(p.line).flex_none())
        }
        let ink = if item.destructive { p.danger } else { p.ink };
        let row_name = item.label.clone();
        let mut row = div()
            .id(("menu-item", i))
            .debug_selector(move || row_name.to_string())
            .role(Role::MenuItem)
            .aria_label(item.label.clone())
            .relative()
            .h(px(row_height))
            .flex_none()
            .flex()
            .items_center()
            .gap(px(9.))
            .px(px(10.))
            .text_size(px(14.))
            .text_color(ink)
            .opacity(if item.disabled {
                0.4
            } else {
                ease((age - i.min(4) as f32 * 0.024) / 0.16)
            })
            .when(active == Some(i), |e| e.aria_active_descendant());
        if let Some(checked) = item.checked {
            row = row
                .role(Role::MenuItemCheckBox)
                .aria_toggled(checked.into());
        }
        if let Some(g) = item
            .glyph
            .or(item.checked.filter(|v| *v).map(|_| Glyph::Check))
        {
            row = row.child(icon(
                g,
                16.,
                if item.destructive { ink } else { p.secondary },
            ))
        }
        row = row.child(div().flex_1().truncate().child(item.label));
        if !sheet && !item.shortcut.is_empty() {
            row = row.child(
                div()
                    .text_size(px(11.))
                    .text_color(p.faint)
                    .child(item.shortcut),
            )
        }
        if let Some(tail) = v.accessory(i, cx, w) {
            row = row.child(tail)
        }
        if !item.disabled && is_open {
            row = row
                .cursor_pointer()
                .on_mouse_move(cx.listener(move |v, _, w, cx| {
                    let m = v.core();
                    if m.active != Some(i) {
                        let t = m.top(i);
                        if m.active.is_none() {
                            m.highlight.reset(t)
                        } else {
                            m.highlight.set(t, cx)
                        }
                        m.active = Some(i);
                        m.focus.focus(w, cx);
                        cx.notify()
                    }
                }))
                .on_click(cx.listener(move |v, _, w, cx| {
                    if v.core().open {
                        v.selected(i, w, cx)
                    }
                    cx.stop_propagation()
                }));
        }
        panel = panel.child(row);
    }
    if sheet {
        let scrim = div()
            .id("sheet-scrim")
            .w(size.width)
            .h(size.height)
            .occlude()
            .bg(black().opacity(0.28 * anim))
            .on_click(cx.listener(|v, _, w, cx| {
                v.core().close(w, cx);
                cx.notify()
            }));
        root = root.child(
            deferred(anchored().position(point(px(0.), px(0.))).child(scrim)).with_priority(2),
        );
    }
    root.child(deferred(anchored().position(point(px(x), px(y))).child(panel)).with_priority(3))
        .into_any_element()
}
